type ormScansessV2 struct {
	c0   Cell[int64]
	c1   Cell[string]
	c2   PtrCell[time.Time]
	c3   PtrCell[string]
	dest []any
}

func (s *ormScansessV2) Dest() []any {
	if s.dest == nil {
		s.dest = []any{&s.c0, &s.c1, &s.c2, &s.c3}
	}
	return s.dest
}

func (s *ormScansessV2) Bind(row any) {
	r := row.(*sessV2)
	*r = sessV2{}
	s.c0.P = &r.ID
	s.c1.P = &r.Token
	s.c2.P = &r.UnlocksAt
	s.c3.P = &r.Note
}

func (s *ormScansessV2) Values(row any, dst []any) []any {
	r := row.(*sessV2)
	return append(dst[:0], r.ID, r.Token, PtrValue(r.UnlocksAt), PtrValue(r.Note))
}

